import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"5.3 Summarize and evaluate reusable methods","description":"New methods start as candidates and are adopted only after evaluation and a small trial.","frontmatter":{"title":"5.3 Summarize and evaluate reusable methods","description":"New methods start as candidates and are adopted only after evaluation and a small trial.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-5/5-3.md","filePath":"en/delivery/stage-5/5-3.md","lastUpdated":1794015952000}'),o={name:"en/delivery/stage-5/5-3.md"};function i(n,e,l,d,u,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_5-3-summarize-and-evaluate-reusable-methods" tabindex="-1">5.3 Summarize and evaluate reusable methods <a class="header-anchor" href="#_5-3-summarize-and-evaluate-reusable-methods" aria-label="Permalink to &quot;5.3 Summarize and evaluate reusable methods&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Candidates are generated from finished task traces; permissions are the intersection of the source task capabilities; baseline and trial records capture success rate, duration, tokens, and approval count; evaluation distinguishes improved, flat, regressed, and insufficient; promotion, rejection, and rollback keep reasons and audit.</li><li><strong>Still open:</strong> A &quot;trial&quot; only reads existing finished traces as evidence and is not a live shadow executor; there is no long-term production comparison of adopted methods.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth summarize reusable methods from successful tasks, but new methods start only as candidates and must pass evaluation and a small trial before becoming official capabilities.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Extract common steps from several successful real tasks into a candidate method with scope and examples.</li><li>Prepare success samples, failure samples, and comparison results for the candidate; do not cherry-pick favorable data.</li><li>Trial it without real impact first, then on a small set of real tasks.</li><li>During the trial, compare success rate, manual time, cost, and failure types in a way the user can understand.</li><li>A new method cannot expand permission automatically, and high-risk actions still require approval.</li><li>Keep the old version so it can be restored immediately if something goes wrong.</li></ol>',7)])])}const p=a(o,[["render",i]]);export{h as __pageData,p as default};
